WITH filtered AS (SELECT id, session_id, event_time, duration_sec, DATEDIFF(CURRENT_DATE(), event_time) AS days_since_event_time, COALESCE(duration_sec, 0) AS duration_sec_filled FROM web_events WHERE session_id IN (14, 29, 37)) SELECT id, session_id, event_time, duration_sec, days_since_event_time, duration_sec_filled, MIN(duration_sec) OVER (PARTITION BY session_id) AS session_id_min_duration_sec, SUM(duration_sec) OVER (PARTITION BY session_id ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec, AVG(duration_sec_filled) OVER (PARTITION BY session_id ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS duration_sec_filled_avg_30d FROM filtered;
